import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CQxpk36T.js";const p=JSON.parse('{"title":"3D rendering","description":"","frontmatter":{},"headers":[],"relativePath":"en/developpement/rendu.md","filePath":"en/developpement/rendu.md","lastUpdated":1793574169000}'),n={name:"en/developpement/rendu.md"};function o(s,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="_3d-rendering" tabindex="-1">3D rendering <a class="header-anchor" href="#_3d-rendering" aria-label="Permalink to &quot;3D rendering&quot;">​</a></h1><p>The goal: a cosy model, smooth on a phone, that doesn&#39;t drain its battery.</p><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><p>Materials are three.js <code>MeshStandardMaterial</code>s with patterns grafted in GLSL (<code>src/scene/shaders.ts</code>): render, half-timbering, tiles, cobbles, grass, wood. <strong>Shared uniforms</strong> carry the time, wind, rain and snow; a single place is enough for everything to get wet or turn white.</p><h2 id="few-draw-calls" tabindex="-1">Few draw calls <a class="header-anchor" href="#few-draw-calls" aria-label="Permalink to &quot;Few draw calls&quot;">​</a></h2><ul><li>One draw call <strong>per material and per building</strong>: merged geometries.</li><li>Repeated details (windows, shutters, logs, solar modules, bushes) as <code>InstancedMesh</code>.</li></ul><h2 id="precomputed-lighting" tabindex="-1">Precomputed lighting <a class="header-anchor" href="#precomputed-lighting" aria-label="Permalink to &quot;Precomputed lighting&quot;">​</a></h2><p>Ambient occlusion and lantern light are computed once, with rays on a BVH (<a href="https://github.com/gkjohnson/three-mesh-bvh" target="_blank" rel="noreferrer">three-mesh-bvh</a>) in a Web Worker, and stored <strong>per vertex</strong>. The result is kept in IndexedDB from one visit to the next. Lanterns have no real point light: it would cost on every pixel and force shaders to recompile at the day / night switch; their precomputed light is simply dosed.</p><h2 id="on-demand-rendering" tabindex="-1">On-demand rendering <a class="header-anchor" href="#on-demand-rendering" aria-label="Permalink to &quot;On-demand rendering&quot;">​</a></h2><ul><li>The image is only redrawn <strong>when something moves</strong>.</li><li>Ambience (wind, clouds, animals) runs at a reduced rate.</li><li>The shadow map is only redone when the sun or a door moves.</li></ul><h2 id="adaptive-quality" tabindex="-1">Adaptive quality <a class="header-anchor" href="#adaptive-quality" aria-label="Permalink to &quot;Adaptive quality&quot;">​</a></h2><p>A pixel budget and GPU time measurement set the resolution. Post-processing (glow, selection outline, tilt-shift blur) is only on in high quality.</p><h2 id="skewed-gables" tabindex="-1">Skewed gables <a class="header-anchor" href="#skewed-gables" aria-label="Permalink to &quot;Skewed gables&quot;">​</a></h2><p>A section is built as a rectangle, then a <strong>shear along x only, depending on z</strong> moves its ends onto their oblique lines (<code>skewGeometry</code>). Since roof slopes have y depending only on z, they stay perfectly flat; normals are transformed by the inverse transpose.</p><h2 id="cutaway-view" tabindex="-1">Cutaway view <a class="header-anchor" href="#cutaway-view" aria-label="Permalink to &quot;Cutaway view&quot;">​</a></h2><p>A <strong>cutting box</strong> (clipping planes set once on every material) hides what sticks out within the building&#39;s footprint; the floor is generated from <code>plans.ts</code>. A scene event filter keeps clicks away from what the cut hides: tapping a room&#39;s floor reaches the room, not the invisible ceiling above.</p><ul><li><strong>Neighbours</strong> are cut at the same height instead of being dithered: the fading test simply discards what is above the cutting height in their footprint.</li><li><strong>The cut walls</strong> get a solid top just below the cutting height (walls are hollow): the openings it crosses stay open, and the filler between plan and wall opens at windows to show their reveal from inside.</li><li><strong>Lit rooms</strong> receive the light of a ceiling lamp (<code>src/scene/roomLamps.ts</code>): no real three.js light, which would recompile every material, but a warm light computed in the materials, bounded to the room. The rest of the interior is in shade, like an interior.</li></ul><h2 id="fading" tabindex="-1">Fading <a class="header-anchor" href="#fading" aria-label="Permalink to &quot;Fading&quot;">​</a></h2><p>When a building is selected, the others switch to <strong>dithering</strong>: some of the pixels are discarded following a regular pattern, with no transparency sorting. The &quot;inside another building&#39;s footprint&quot; test is grafted once into every material; clicks go through what is faded when the selected building is behind.</p><h2 id="tap-or-drag" tabindex="-1">Tap or drag <a class="header-anchor" href="#tap-or-drag" aria-label="Permalink to &quot;Tap or drag&quot;">​</a></h2><p>A touch that moves more than 12 pixels (<code>TAP_SLOP</code>, <code>src/scene/tap.ts</code>) is a drag: it rotates the camera without acting on what&#39;s underneath.</p>',21)])])}const u=t(n,[["render",o]]);export{p as __pageData,u as default};
